[exhibition] {
  "core_planning_data": {
    "standard_compliance": {
      "mandatory_zones": "常设展厅、短期展厅、报告厅、影像厅、科普活动室 (来源: 片段3 | 科学技术馆建设标准); 为展示适于学龄前儿童的展品而设置的展厅 (来源: 片段4 | 博物馆建筑设计规范)",
      "area_ratios": "Standard Not Found",
      "spatial_requirements": "同一时间展厅单位面积合理接待观众的最高数量为 0.20人/m²~0.25人/m²，部分管理人员建议以 0.30人/m² 为最高限额 (来源: 片段1 | 博物馆建筑设计规范 条文说明); 展品所占面积平均值参考为 23.1 m²/件 (来源: 片段2 | 科学技术馆建设标准 条文说明)"
    },
    "baseline_themes": [
      {
        "theme_name": "科学与技术基础",
        "typical_ratio": "[General Knowledge]",
        "description": "基本科学、工程与工业文明的常设叙事。",
        "reference": "[General Knowledge]"
      }
    ]
  },
  "trend_analysis_data": {
    "global_trends": [
      {
        "trend_name": "Hybrid Exhibition Ecosystems",
        "description": "Modern science museums are increasingly adopting a dual-structure spatial strategy that combines permanent core collections with flexible temporary galleries. This approach ensures the longevity of foundational scientific knowledge while allowing the institution to remain current with rapid technological advancements.",
        "evidence_cases": [
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "35,000 sqm of permanent and temporary exhibition halls and galleries."
          },
          {
            "case_name": "Museum of Medical History and Innovation",
            "snippet": "core and changing exhibition galleries"
          }
        ],
        "is_general_knowledge": false
      },
      {
        "trend_name": "Rest-Integrated Circulation Design",
        "description": "To enhance the visitor experience and combat museum fatigue, contemporary designs are embedding rest zones, terraces, and viewing platforms directly into the exhibition route. These spaces serve as functional pauses for contemplation and visual orientation within the larger narrative.",
        "evidence_cases": [
          {
            "case_name": "Yibin Science and Technology Museum",
            "snippet": "enter the second-floor exhibition hall, where you can have a good view and rest."
          },
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "Terraces provide places for rest and contemplation while exploring the exhibitions."
          }
        ],
        "is_general_knowledge": false
      },
      {
        "trend_name": "Atrium-Centric Spatial Organization",
        "description": "Large-scale science museums are utilizing grand central atriums not just as lobbies, but as the organizational core from which thematic halls radiate or 'float.' This layout provides visual clues for intuitive navigation and physically interconnects diverse scientific disciplines.",
        "evidence_cases": [
          {
            "case_name": "New Science and Technology Museum of Henan Province",
            "snippet": "Nearly 20 large exhibition halls themed around \"Nature, Astronomy, and Intelligence\" radiating from the atrium's three wings."
          },
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "The many galleries emerge from the floor and walls of its central atrium... each giving visual clues that intuitively direct visitors through the museum's series of interconnected spaces."
          }
        ],
        "is_general_knowledge": false
      }
    ],
    "innovative_features": [
      "Integration of multi-disciplinary themes (Nature, Astronomy, Intelligence) within a single complex (Henan Province).",
      "Visual clues embedded in architecture to intuitively direct visitors without heavy reliance on signage (Shenzhen).",
      "Floating gallery volumes that utilize the verticality of the atrium to create a dynamic spatial composition (Shenzhen).",
      "Designated viewing and resting points within exhibition halls to ensure continuity of experience (Yibin)."
    ]
  },
  "generated_at": "2025-12-07T16:39:16.234595"
}
